# `base::match.arg()` says `'arg'` in its messages and reports its own frame;
# this names the argument and raises an argument error
# (`.miniextendr_arg_error`) attributed to `call`: by default the wrapper's own
# call, for a `call = caller` wrapper its caller's matched call.
# Semantics follow `match.arg(arg, choices)`: `NULL` and the full choice vector
# (the formal default) select the first choice; otherwise exactly one string
# that matches a choice exactly or as a unique prefix. A factor is read as its
# labels. `aliases`, a named character vector (`c(grey = "gray")`), maps a
# string typed exactly as an alias to its choice; a prefix of an alias is not
# one. `listed` is the text the message names the listed aliases with after
# the choices (` (or "grey" for "gray")`, empty when none is listed). `NA`
# is matched as the string "NA", as `pmatch()` does; when that matches no
# choice, or the value is not character and holds `NA`, it is refused as
# `must not be NA`, the wording of a `no_na` parameter. The Rust side's
# `match_arg_param()` gives a body the same results and messages for a choice
# argument it matches itself.
.miniextendr_match_arg <- function(arg, choices, arg_name, call = sys.call(-1L), aliases = NULL, listed = "") {
  if (is.null(arg)) return(choices[[1L]])
  if (is.factor(arg)) arg <- as.character(arg)
  if (!is.character(arg)) .miniextendr_arg_error(arg_name, if (is.atomic(arg) && anyNA(arg)) "must not be NA" else "must be NULL or a character vector", call)
  if (identical(arg, choices)) return(arg[[1L]])
  if (length(arg) != 1L) .miniextendr_arg_error(arg_name, "must be of length 1", call)
  if (!is.null(aliases) && !is.na(a <- match(arg, names(aliases)))) return(aliases[[a]])
  i <- pmatch(arg, choices, nomatch = 0L, duplicates.ok = TRUE)
  if (is.na(i) || i == 0L) {
    if (is.na(arg)) .miniextendr_arg_error(arg_name, "must not be NA", call)
    .miniextendr_arg_error(arg_name, sprintf("should be one of %s%s", paste(dQuote(choices, FALSE), collapse = ", "), listed), call)
  }
  choices[[i]]
}

